package com.finguard.util;
import java.math.BigDecimal; import java.time.*; import java.util.*; import com.finguard.model.*;
public final class InputValidator { private InputValidator(){} public static void validate(String account,String ref,BigDecimal amount,String currency,TransactionType type,String merchant,LocalDateTime time){if(blank(account))throw new IllegalArgumentException("Account ID is required");if(blank(ref))throw new IllegalArgumentException("Reference is required");if(amount==null||amount.signum()<0)throw new IllegalArgumentException("Amount must be zero or positive");if(blank(currency)||!currency.matches("[A-Za-z]{3}"))throw new IllegalArgumentException("Currency must be a 3-letter code");if(type==null)throw new IllegalArgumentException("Type must be CREDIT or DEBIT");if(blank(merchant))throw new IllegalArgumentException("Merchant/recipient is required");if(time==null)throw new IllegalArgumentException("Timestamp is required");} private static boolean blank(String s){return s==null||s.isBlank();} public static TransactionType type(String s){return TransactionType.valueOf(s.trim().toUpperCase(Locale.ROOT));} public static LocalDateTime timestamp(String s){return LocalDateTime.parse(s.trim());} }
